ProjectALife.DialogueShards["replies_ask_20"] = {
{"ASK_NOISE","reg=civilian,family,worker,rescue|tmp=fresh|st=friendly,neutral",{"YES, keep it down, please. I don't know what's within earshot and I don't want to find out by shouting","I worry about every cough and footstep now. I know that sounds mad, but please talk quietly","Gunshots scare the hell out of me. One more reason not to fire unless you have to","Whisper, please. And look where you're walking; I'm nervous enough without you rushing ahead","I stopped talking out loud on the second day... I use my hands now, like a mime, a very scared mime!"}},
{"ASK_NOISE","reg=civilian,family,worker,rescue|tmp=seasoned|st=friendly,neutral",{"Noise can bring trouble. Keep your voice low, and don't take being quiet for being safe","I fired once and had more trouble than I wanted. I don't know how far it carried; I remember having to run","I'd avoid breaking a window if there's another way in. No sense making a racket for nothing","They don't need to understand the conversation for noise to be a problem. Let's keep ours down","Keep your voice below a whisper, your steps soft, your breathing slow, and your fears to yourself"}},
{"ASK_NOISE","reg=civilian,family,worker,rescue|st=friendly",{"You're right to ask, quiet's the best weapon we've got, and there are tricks, small ones"}},
{"ASK_NOISE","reg=civilian,family,worker,rescue|st=careful",{"You're making noise right now, keep it down","Shut up and listen -- if you hear anything, that's the answer","Yes.. keep your voice low and give me some room","They hear it.. I don't want this talk carrying any farther than it has to"}},
{"ASK_NOISE","role=civilian_loner",{"Don't rush through the woods. Stop and listen now and then; it's easy to get careless when you're tired"}},
{"ASK_NOISE","role=family_man,family_woman",{"The kids know to whisper, they know to freeze, we practice it like a game"}},
{"ASK_NOISE","role=militia",{"Noise discipline, always, even a radio squelch can give us away"}},
{"ASK_NOISE","role=rescue_medical|st=friendly,neutral",{"I ask people to lower their voices. Fear can get a whole room talking at once","Noise can draw them. I ask for quiet, but I'm not going to yell at somebody for being frightened"}},
{"ASK_NOISE","role=rescue_medical|st=careful",{"Quiet, please, you're making noise"}},
{"ASK_NOISE","role=civilian_loner|st=friendly,neutral",{"Noise carries","Don't count on some little trick to make you silent","Stop and listen before you choose a way through"},false,false,{[1]={{t="a snapped twig sounds like a rifle shot",afterMs=3500}},[2]={{t="tie your gear tight",afterMs=3200}}}},
{"ASK_NOISE","role=civilian_loner|st=careful",{"Quiet!!"}},
{"ASK_NOISE","reg=civilian,family,worker,rescue|st=friendly,neutral|day=0,99999|hour=22,4",{"Nights are loud, even when they're quiet","Be quiet","It's dark. Keep your voice low and don't wander off while we're talking"},false,false,{[1]={{t="every creak carries",afterMs=3500}},[2]={{t="the night has big ears",afterMs=3200}}}},
{"ASK_NOISE","reg=civilian,family,worker,rescue|st=friendly,neutral|day=0,99999|hour=5,10",{"Morning's no excuse to start making a racket. Keep a little attention for what's around us","Even a whisper stands out in the dawn hush"}},
{"ASK_NOISE","reg=civilian,family,worker,rescue|st=friendly,neutral|day=0,99999|hour=11,18",{"It's daylight, not a free pass. I'd still rather keep this conversation quiet"}},
{"ASK_NOISE","reg=civilian,family,worker,rescue|st=friendly,neutral|day=0,99999|hour=19,21",{"Evening's the time to pipe down"},false,false,{[1]={{t="the quiet is coming",afterMs=3500}}}},
{"ASK_NOISE","reg=civilian,family,worker,rescue|st=friendly,neutral|mood=fear",{"Shhh!! Not so loud!! I keep thinking they'll hear us!","E- every little noise makes me flinch. I can't help it"}},
{"ASK_NOISE","reg=civilian,family,worker,rescue|st=friendly,neutral|mood=angry",{"Stop making noise, you'll get us killed, you idiot"}},
{"ASK_NOISE","reg=civilian,family,worker,rescue|st=friendly,neutral|mood=funny",{"Silent as a mouse, that's me!"},false,false,{[1]={{t="a very large mouse",afterMs=3200}}}},
{"ASK_NOISE","reg=raider|st=neutral,careful",{"Noise? Yeah, it brings them, but it also brings fools like you to me, so I'm not complaining","Be quiet, genius, you're louder than a hog in a thunderstorm","A gunshot can draw trouble, so don't pull that trigger unless it's worth it","Don't ask me how far they hear. Keep your damn voice down and don't test it","Keep your voice down and your boots soft, or you'll be dinner"}},
{"ASK_NOISE","reg=raider|st=hostile",{"Shut up, you're making too much noise!"}},
{"ASK_NOISE","reg=raider|st=friendly",{"Yeah, noise is bad. I once stuffed socks in my boots thinking it'd help. Mostly I just hurt my feet"}},
{"ASK_NOISE","reg=gang|st=neutral,careful",{"Quiet, always quiet. I don't want to be the one that brings trouble over here","Never shoot unless you have to, the bang is a dinner bell","Use a knife, a bat, anything that doesn't go boom"}},
{"ASK_NOISE","reg=gang|st=hostile",{"Quiet down, or I'll quiet you permanently!"}},
{"ASK_NOISE","reg=gang|st=friendly",{"I whisper everything now, even in my sleep, my girl says I scare her"}},
{"ASK_NOISE","reg=club|st=neutral,careful",{"Loud pipes save lives, they used to say, now they get you killed","Whispers only, {g:brother|sister}, even when you're drunk","Keep your engine off and your voice down"}},
{"ASK_NOISE","reg=club|st=hostile",{"Noise? You're the noise, and I'm about to silence you!"}},
{"ASK_NOISE","reg=club|st=friendly",{"I lost three friends to a single gunshot, never again"}},
{"ASK_NOISE","reg=crime|st=neutral,careful",{"Discretion is paramount, in all things","Noise is the enemy of survival, as it was of my profession"}},
{"ASK_NOISE","reg=crime|st=friendly",{"I've learned to move like a ghost, it's served me well"}},
{"ASK_NOISE","reg=prison|st=neutral,careful",{"Shh, shh, don't talk so loud, they'll hear us, they'll hear us!","I learned silence in the cell, now it saves my life"}},
{"ASK_NOISE","reg=prison|st=hostile",{"Shut up! SHUT UP! They'll hear you!"}},
{"ASK_NOISE","reg=prison|st=friendly",{"Please, keep your voice low, I'm begging you"}},
{"ASK_NOISE","reg=outlaw|st=neutral,careful",{"Keep your voice down in the hills. I don't know who else is out there listening","Never fire unless you must, the echo gives you away"}},
{"ASK_NOISE","reg=outlaw|st=friendly",{"I move slow, speak soft, and breathe quiet"}},
{"ASK_NOISE","reg=law|st=neutral,careful",{"Kill the sirens and keep radios low, noise brings them","Keep voices low and weapons holstered unless necessary","Gunfire draws the infected, use it sparingly"}},
{"ASK_NOISE","reg=law|st=hostile",{"Quiet! Shut it!"}},
{"ASK_NOISE","reg=law|st=friendly",{"Whisper when you can, it works, believe me"}},
{"ASK_NOISE","reg=military|st=neutral,careful",{"Hand signals, not talking, noise gets us found","I'd rather avoid a shot if we can. Don't make a promise you can't keep about how quiet a gun will be"}},
{"ASK_NOISE","reg=military|st=friendly",{"Just keep it down. I'd like to get through this without any more surprises"}},
{"ASK_NOISE","role=soldier_green|st=neutral,careful",{"I dropped my canteen once and it sounded like a gunshot, we had to run for an hour"}},
{"ASK_NOISE","role=militia|st=neutral,careful",{"My uncle hunted with a bow. Me, I'd be glad just to find supper without firing a shot","Never fire near the house, the dead come running"}},
{"ASK_NOISE","role=militia|st=friendly",{"Quiet prayers, friend, quiet footsteps, quiet hearts"}},
{"ASK_NOISE","reg=civilian,family|tmp=fresh|st=friendly,neutral|world=generator",{"Yes! Oh my God, yes - Mr. Hollis started his generator and by morning his whole yard was full of them"}},
{"ASK_NOISE","reg=family|tmp=fresh|st=friendly,neutral",{"My boy dropped a pot lid and I thought my heart would stop. Please talk quieter; I'm jumpy enough"}},
{"ASK_NOISE","reg=civilian,family|tmp=fresh|st=friendly,neutral|world=vehicle,road",{"I think so, car alarms went off on our street the first night, and they came from everywhere"}},
{"ASK_NOISE","reg=civilian,family|tmp=fresh|st=friendly,neutral|sex=f",{"I stopped wearing my bracelets because they jingle - silly, huh? I loved those bracelets"}},
{"ASK_NOISE","reg=civilian,family|tmp=seasoned,veteran|st=friendly,neutral",{"A gunshot can draw company you don't want. Shoot like it costs you something, 'cause it does"}},
{"ASK_NOISE","reg=civilian,family|tmp=seasoned,veteran|st=friendly,neutral|world=vehicle,generator",{"Noise is a dinner bell, a car alarm's a church bell, a generator's a whole marching band"}},
{"ASK_NOISE","reg=civilian,family,worker|tmp=seasoned,veteran|st=friendly,neutral",{"Don't rely on a clever little trick to keep you quiet. Take your time and watch what you're doing"}},
{"ASK_NOISE","reg=civilian,family|tmp=seasoned,veteran|st=friendly,neutral|world=road",{"A distraction's no promise of a clear way out. Watch what they actually do before you make your move"}},
{"ASK_NOISE","reg=civilian,family,worker,rescue|st=hostile",{"They hear noise.. and I don't want company so get lost"}},
{"ASK_NOISE","reg=worker|st=friendly,neutral",{"Plant horn went off at shift change the second day - Automatic timer, pulled them in from all over town","Chainsaw's about the worst thing you can run, might as well hit a dinner bell with a sledgehammer"}},
{"ASK_NOISE","reg=rescue|role=rescue_firefighter|st=friendly,neutral|world=vehicle",{"We ran the siren day one to clear traffic, worst call of my career - they followed the engine for miles"}},
{"ASK_NOISE","reg=rescue|role=rescue_medical|st=friendly,neutral",{"I remember trying to calm a mother while her baby cried. She was terrified we'd be heard, and so was I"}},
{"ASK_NOISE","reg=rescue|role=rescue_clergy|st=friendly,neutral",{"We quit ringing the bell, the Lord hears us fine at a whisper"}},
{"ASK_NOISE","reg=law,swat|st=friendly,neutral",{"It does.. if you're carrying a gun don't fire unless you have to.. every shot draws attention"}},
{"ASK_NOISE","reg=law|st=friendly,neutral|world=cars",{"Sirens pulled them to the cruisers day one, we learned fast, lights only, and then nothing"}},
{"ASK_NOISE","reg=law,swat|st=careful,hostile",{"Quiet down and step back"}},
{"ASK_NOISE","reg=military|st=friendly,neutral",{"Gunfire can draw the infected. I can't give you a safe distance; avoid the shot if you can"}},
{"ASK_NOISE","reg=military|tmp=seasoned,veteran|st=friendly,neutral|world=generator",{"We lost a checkpoint to a generator, loudest thing for miles, and they all came to it"}},
{"ASK_NOISE","reg=elite",{"Don't fire just to solve a problem you haven't looked at yet"}},
{"ASK_NOISE","reg=military|st=careful,hostile",{"Quiet - now - back off"}},
{"ASK_NOISE","reg=outlaw,raider,crime|st=friendly,neutral",{"A horn might bring them out, or leave plenty inside. I don't call that a cleared house"}},
{"ASK_NOISE","reg=prison|st=friendly,neutral",{"Riot bell at the prison rang two days straight. Nobody to shut it off. I haven't gone back to see what's there now"}},
{"ASK_NOISE","reg=gang|st=friendly,neutral|world=vehicle,road",{"We tried leaving a boombox behind us once. I still checked the shops before stepping inside; not everybody takes the bait"}},
{"ASK_NOISE","reg=club|st=friendly,neutral",{"Loud pipes save lives, we used to say, now we ride slow and quiet"}},
{"ASK_NOISE","reg=outlaw,raider,gang,club,crime,prison|st=hostile",{"Shout all you want, nobody's coming to help - Plenty's coming, though"}},
{"ASK_NOISE","reg=outlaw,raider,gang,club,crime,prison|st=careful,hostile",{"Keep it down, or I'll keep it down for you"}},
{"ASK_NOISE","reg=civilian|tmp=fresh|st=friendly,neutral",{"Yes! Everything! I dropped a pan on the fourth and I'm still thinking about it"}},
{"ASK_NOISE","reg=family|st=neutral|world=building",{"We put rugs down in the kitchen. Felt like making a home again, even if it didn't solve a damn thing"}},
{"ASK_NOISE","reg=worker|tmp=seasoned|st=neutral|world=vehicle",{"I'd rather not leave an engine running for nothing. More noise than I care to make"}},
{"ASK_NOISE","role=rescue_medical|st=neutral|mood=grim",{"A scream scares me more than anything now. You want to help, but you don't know what's waiting"}},
{"ASK_NOISE","reg=civilian|tmp=seasoned|st=neutral|world=road",{"Talk low and watch your route. I wouldn't trust the grass to keep you hidden any more than the road"}},
{"ASK_NOISE","role=law_deputy|st=neutral",{"Sirens were the worst mistake we made that first week - every one of us made it"}},
{"ASK_NOISE","role=soldier_nco|tmp=veteran|st=neutral",{"One shot can bring more trouble. Think on that before you touch a trigger"}},
{"ASK_NOISE","role=elite_delta|tmp=veteran|st=neutral",{"Don't put a number on how far a sound carries. Plan for somebody hearing it, and keep looking"}},
{"ASK_NOISE","reg=club|st=neutral",{"A bike is a dinner bell, I push it the last quarter mile every time now"}},
{"ASK_NOISE","role=crime_member|st=neutral",{"Make your noise somewhere else and keep my corner quiet - that's how business gets done here"}},
{"ASK_NOISE","role=civilian_loner|st=careful|mood=grim",{"I dreamed about the saw at work last night. Same cut, over and over. Woke up listening for it"}},
{"ASK_NOISE","reg=raider,gang|tmp=predator|st=hostile",{"We like noise, noise means somebody's careless, and careless means we eat"}},
{"ASK_OKAY","reg=civilian,family,worker,rescue|tmp=fresh|st=friendly,neutral",{"Me? Oh, I'm- yeah, I'm okay, I'm fine, I'm totally, completely fine, don't look at me like that","No, not really... I didn't think it showed that much","I'm hanging in there... barely, but I'm hanging!","Okay? Ha! that's a good one, no, I'm not okay, but I'm alive, which is something","Tired, scared, and trying not to take it out on anybody","I'm fine... I just need a minute, a minute to breathe, and I'll be fine","Honestly? I'm a mess, but I'm a mess who's still on his feet"}},
{"ASK_OKAY","reg=civilian,family,worker,rescue|tmp=seasoned|st=friendly,neutral",{"I'm okay, as okay as anyone gets these days, which isn't very okay, but it'll do","Sore... tired, and a little grumpy, otherwise fine","Alive, which is more than I can say for a lot of folks","I'm good, thanks, really, no need to worry about me"}},
{"ASK_OKAY","reg=civilian,family,worker,rescue|st=friendly",{"I haven't slept worth a damn. It's making everything harder","I'm getting by. How are you holding up?","Nobody's asked me that in days","Okay? Ha, define okay. I'm here, and I'm tired of thinking about it","Not really, not really at all, but I'm still here, which counts for something","I'm getting by. I don't feel up to much more than this conversation","Ask me tomorrow. I might have worked out an honest answer","I can't keep my thoughts on one thing. Even a simple question feels like work","I'm good, I'm good, I'm good, I keep saying it and it keeps being a lie"},false,false,{[3]={{t="that's the nicest thing anyone's said today",afterMs=3200}}}},
{"ASK_OKAY","reg=civilian,family,worker,rescue|st=careful",{"I'm fine, don't come closer","Since when do you care?","I'm fine, and I'd like to stay that way","I'm fine, back off","I'm fine, thanks, now back up","Okay enough, why?","I'm fine from over there - stay over there"}},
{"ASK_OKAY","role=rescue_medical|st=friendly,neutral",{"I'm fine, I'm the one who's supposed to ask you that, so, how are YOU?","I'm okay, I'm a pro, I look okay on the outside, don't look too close","No, I'm not doing well. Give me a minute before you need anything from me"}},
{"ASK_OKAY","role=rescue_clergy|st=friendly,neutral",{"I'm well, by the grace of God, and a lot of coffee"}},
{"ASK_OKAY","role=rescue_medical|st=careful",{"I'm fine -- and I don't need your concern"}},
{"ASK_OKAY","reg=civilian,family,worker,rescue|st=friendly,neutral",{"Yeah -- yeah, I'm okay","I'm fine","Worn out. Don't have much more of an answer","Okay is a big word","I'm hanging in","I don't want to get into it","I'm okay","I'd rather not start listing everything"},false,false,{[1]={{t="tired, mostly",afterMs=3500},{t="tired and a little sore",afterMs=3000}},[2]={{t="I'm always fine",afterMs=3200},{t="ask my mother",afterMs=2800}},[3]={{t="like a boot",afterMs=3500}},[4]={{t="I'm upright, and I'm breathing",afterMs=3200},{t="is that okay?",afterMs=2800}},[5]={{t="most days, anyway",afterMs=3500},{t="don't ask me about tomorrow",afterMs=3000}},[6]={{t="I just don't feel like talking about my body",afterMs=3200}},[7]={{t="really",afterMs=3500},{t="okay as in not dead, that's about it",afterMs=3000}},[8]={{t="the rest, well",afterMs=3200}}}},
{"ASK_OKAY","reg=civilian,family,worker,rescue|st=friendly,neutral|mood=funny",{"Okay? I'm gorgeous, can't you tell?!","Fit as a fiddle, which is to say, out of tune!"}},
{"ASK_OKAY","reg=raider|st=neutral,careful",{"I'm fine, why? Are you looking for a weak spot?","Okay? Define okay, because I haven't slept in three days and I'm seeing things","I'm alive, isn't that enough? Don't make it complicated","Me? I could use a week of sleep. Maybe then I'd have the patience for this conversation","I'm fine, quit staring, you're making it weird"}},
{"ASK_OKAY","reg=raider|st=hostile",{"Why, hoping to hear something bad? I'm not giving you the satisfaction"}},
{"ASK_OKAY","reg=raider|st=friendly",{"Honestly? No, not really... nobody asks, so, yeah, thanks","I... yeah, I'm okay, I'm just... it's been a lot, you know?"}},
{"ASK_OKAY","reg=gang|st=neutral,careful",{"I'm getting by. Don't make it a thing","Nah, I'm straight, stop worrying about me","Other ways? Don't ask. I'd rather leave it there"}},
{"ASK_OKAY","reg=gang|st=hostile",{"Am I okay? Do you see a problem?!"}},
{"ASK_OKAY","reg=gang|st=friendly",{"Not really, but I'll get through it, I always do"}},
{"ASK_OKAY","reg=club|st=neutral,careful",{"I've had worse, {g:brother|sister}, a lot worse","I'm getting by. Wish that were a better answer","Don't worry about me, worry about yourself"}},
{"ASK_OKAY","reg=club|st=hostile",{"Oh, NOW you care?!"}},
{"ASK_OKAY","reg=club|st=friendly",{"Not great, but don't fuss over me"}},
{"ASK_OKAY","reg=crime|st=neutral,careful",{"Peachy, don't trouble yourself","Exhausted, mostly. Don't fuss over me"}},
{"ASK_OKAY","reg=crime|st=friendly",{"Tired, mostly. That's about as much as I want to say"}},
{"ASK_OKAY","reg=prison|st=neutral,careful",{"I'm okay, I'm okay, I'm fine, why do you keep asking?"}},
{"ASK_OKAY","reg=prison|st=neutral,careful|world=building",{"Hurt? I don't feel anything, that's the problem, I haven't felt anything since the walls came down"}},
{"ASK_OKAY","reg=prison|st=hostile",{"Don't look at me! Don't look at me like I'm hurt!"}},
{"ASK_OKAY","reg=prison|st=friendly",{"No. I don't even know where to start telling you what's wrong"}},
{"ASK_OKAY","reg=outlaw|st=neutral,careful",{"I'm fine, friend, just a little rough around the edges","I keep hoping a walk will settle my head"}},
{"ASK_OKAY","reg=outlaw|st=friendly",{"Been better, been worse, you know how it is"}},
{"ASK_OKAY","reg=law|st=neutral,careful",{"I'm functional, which is all I can ask for","I've felt better. Nothing I want to discuss with you","I'm fine, thank you, let's focus on the matter at hand"}},
{"ASK_OKAY","reg=law|st=hostile",{"Don't worry about me, worry about the situation"}},
{"ASK_OKAY","reg=law|st=friendly",{"I'm hanging in. Don't let the way I look put you off"}},
{"ASK_OKAY","reg=military|st=neutral,careful",{"I don't want to discuss it. Let's keep moving"}},
{"ASK_OKAY","reg=military|st=hostile",{"That's not your concern, civilian"}},
{"ASK_OKAY","reg=military|st=friendly",{"I'm holding up"}},
{"ASK_OKAY","role=soldier_green|st=neutral,careful",{"I'm-- no, no I'm not okay, but I'm not supposed to say that"}},
{"ASK_OKAY","role=militia|st=neutral,careful",{"Sore, tired, but alive, which is more than most can say"}},
{"ASK_OKAY","role=militia|st=friendly",{"I'm all right, neighbor, don't worry about me"}},
{"ASK_OKAY","reg=law,swat|st=careful",{"I'm okay, you?"}},
{"ASK_OKAY","reg=military,elite|st=careful",{"Fine, thanks"}},
{"ASK_OKAY","reg=outlaw,raider,gang,club,crime,prison|st=careful",{"Peachy, what's it to you?","Asking if I'm hurt? Looking for a soft spot? There ain't one"}},
{"ASK_OKAY","reg=civilian,family,worker,rescue|tmp=fresh|st=friendly",{"Am I okay? Oh... no, not really, but nobody ever asks, so, thanks","I'm okay, I think... I'm okay, I keep saying it like it'll make it true","Yeah, yeah, I'm fine, I just... I keep hearing things, you know?","Physically? Sort of, the rest of me... never mind, I don't wanna talk about it","I'm alive, so I guess that's a yes? sorry, I'm a little shaky today"}},
{"ASK_OKAY","reg=civilian,family,worker,rescue|tmp=fresh|st=neutral",{"Why do you ask? Do I look okay? I'm fine, I'm fine, please leave me alone","Okay as I can be, I guess, why, do I look sick?"}},
{"ASK_OKAY","reg=civilian,family,worker,rescue|tmp=seasoned|st=friendly",{"Been better, been worse, I'll live, how about you?","Tired, mostly, tired in the bones, but alive, so that counts","Not great, not terrible, just kind of... flat, you know?","Nobody's okay, but I'm functioning, that's what I've got","Okay? Ha, that's cute, I'm good enough to still be standing, how's that?"}},
{"ASK_OKAY","reg=civilian,family,worker,rescue|tmp=seasoned|st=neutral",{"Mind your own business, but yeah, I'm fine","Fine, why, what are you asking for?"}},
{"ASK_OKAY","reg=family|st=friendly",{"Oh honey, I'm alright, just these old bones, how are you?","Not great, dear, but better now that someone cared enough to ask","I'm fine, dear, my old bones are just grumpy","Tired, mostly, tired to the soul, but alive, thank the Lord"}},
{"ASK_OKAY","reg=law,swat|st=friendly",{"Hanging in there, thanks, you?","I'm functioning, haven't slept in two days, but functioning","Holding up, thanks, you?","Functional, which at this point is a victory"}},
{"ASK_OKAY","reg=law,swat|st=neutral",{"I'm fine, why do you want to know?"}},
{"ASK_OKAY","reg=military,elite|st=friendly",{"I'm all right. You can stop looking so worried","I could use a hot meal and a week of sleep. I'm not looking for a fuss","Operational, thank you","Tired, but I'll manage"}},
{"ASK_OKAY","reg=military,elite|st=neutral",{"Fine, move on"}},
{"ASK_OKAY","reg=outlaw,raider,gang,club,crime,prison|st=friendly",{"Ha, I'm great, never better, can't you tell? Why, you worried about me?","Okay? Nah, but I'm still breathing, so who's complaining","Ha, I've been worse, I've been better. Today I don't feel much like explaining","Okay? Never been better, ask the dead"}},
{"ASK_OKAY","reg=outlaw,raider,gang,club,crime,prison|st=careful,hostile",{"What's it to you? Mind your own damn business","Why, what's it to you?!"}},
{"ASK_OKAY","tmp=veteran|st=friendly",{"Fine, thank you"}},
{"ASK_OKAY","reg=civilian,family,worker,rescue|st=neutral",{"Why do you ask? Do I look bad? Do I?","I'm fine, worry about yourself"}},
{"ASK_OKAY","reg=civilian,family,worker,rescue|st=hostile",{"Okay?! Don't pretend to care!","Better than you're gonna be if you don't back off"}},
{"ASK_OKAY","reg=law,swat|st=hostile",{"I'm fine, hands up"}},
{"ASK_OKAY","reg=military,elite|st=hostile",{"Irrelevant"}},
{"ASK_OKAY","reg=outlaw,raider,gang,club,crime,prison|st=hostile",{"I'm great, I'm about to be greater","I'm great, you, on the other hand, look like you're about to have a real bad day"}},
{"ASK_OKAY","reg=civilian,family|tmp=fresh|st=friendly,neutral",{"I'm okay, I'm, I'm okay. I keep forgetting what I was about to do","Yeah... you're the first person who's asked me anything in days","Not really, but I'm here talking to you. I'll take that"}},
{"ASK_OKAY","reg=civilian,family|tmp=fresh|st=friendly,neutral|world=fence",{"I'd rather take things slowly today. Please don't rush me"},false,{[1]="GENERIC"}},
{"ASK_OKAY","reg=civilian,family|tmp=seasoned|st=friendly,neutral",{"Fine as anybody, sore feet, no sleep, bad coffee - you?","I'm upright, ain't much more to report than that"},false,{[1]="GENERIC"}},
{"ASK_OKAY","reg=rescue|role=rescue_firefighter|st=friendly,neutral",{"I've had enough worrying about injuries to last me a lifetime"}},
{"ASK_OKAY","reg=worker,rescue|st=friendly,neutral",{"I'm alright, been on my feet eighteen hours - ask me again when I sit down"}},
{"ASK_OKAY","reg=law,swat|st=friendly,neutral",{"I'm alright, thank you - would you mind rolling your sleeves up for me? It's procedure now, for everybody","Been better. My pride's taken enough tumbles for one lifetime"},false,{[1]="SHOW_ARMS"}},
{"ASK_OKAY","reg=law,swat|st=careful,hostile",{"I'm fine, you're the one I'm assessing - stay put"}},
{"ASK_OKAY","reg=military|tmp=fresh|st=friendly,neutral",{"I keep wondering if I've overlooked something. Can't settle my mind"}},
{"ASK_OKAY","reg=military,elite|tmp=seasoned,veteran|st=friendly,neutral",{"Operational"}},
{"ASK_OKAY","reg=elite|st=friendly,neutral",{"I'm all right, don't let me keep you"}},
{"ASK_OKAY","reg=military,elite|st=careful,hostile",{"Worry about yourself - don't come any closer"}},
{"ASK_OKAY","reg=outlaw,crime|st=friendly,neutral",{"Been worse, been shot at by the state police twice, and I'm still prettier than both of 'em"}},
{"ASK_OKAY","reg=outlaw,crime|st=friendly,neutral|world=building",{"I used to laugh at my own little accidents. Harder to do that now"}},
{"ASK_OKAY","reg=raider,gang,club|st=friendly,neutral|world=road",{"Never better. That's what you want to hear, isn't it?"}},
{"ASK_OKAY","reg=prison|st=friendly,neutral",{"Took a shank in the ribs in '89 and walked it off - this is a vacation"}},
{"ASK_OKAY","reg=civilian|tmp=fresh|st=friendly,neutral",{"No, but I'm standing and talking, and that's two more than yesterday"}},
{"ASK_OKAY","reg=family|st=friendly,neutral",{"I'm getting by. Ask me again when I don't feel so responsible for everybody"}},
{"ASK_OKAY","reg=worker|tmp=seasoned|st=neutral,friendly",{"I feel worn down. Other than that, I'm in the pink"}},
{"ASK_OKAY","role=rescue_medical|st=neutral",{"I'm fine, I say that about forty times a day and four of 'em are true"}},
{"ASK_OKAY","role=rescue_clergy|st=friendly|mood=warm",{"I'm well... nobody asks the fella that's supposed to be steady, so, thanks"}},
{"ASK_OKAY","role=rescue_firefighter|st=neutral",{"Hard to shake off the old job. I keep trying to act like everything will pass"}},
{"ASK_OKAY","reg=civilian|tmp=seasoned|st=neutral",{"I'm okay, I'm the kind of okay where you don't ask it a second time"}},
{"ASK_OKAY","role=family_elder|st=neutral,friendly",{"I miss my husband. Some days that takes up the whole answer"}},
{"ASK_OKAY","role=law_deputy|st=neutral",{"I'm functional, that's the word I've settled on - functional"}},
{"ASK_OKAY","role=law_sheriff|st=neutral",{"Don't worry about me, {g:son|young lady}, I'm the last one anybody needs to worry over"}},
{"ASK_OKAY","role=soldier_nco|tmp=veteran|st=neutral",{"Combat effective, which ain't the same as okay, but it's what I've got"}},
{"ASK_OKAY","role=soldier_green|tmp=fresh|st=neutral",{"I can't get my thoughts straight today, so, no"}},
{"ASK_OKAY","role=elite_delta|tmp=veteran|st=neutral",{"I'm operational - next question"}},
{"ASK_OKAY","reg=club|st=neutral",{"I miss laughing without thinking something bad will follow"}},
{"ASK_OKAY","role=crime_member|st=neutral",{"I'm real good, ain't that the strangest thing a man's had to admit lately"}},
{"ASK_OKAY","role=civilian_loner|st=careful",{"I was, till somebody walked up on me"}},
{"ASK_OKAY","reg=civilian,family|tmp=fresh|st=careful|mood=sad",{"I'm fine, I'm, I'm fine. Why can't I make a simple thought come out right?"}},
{"ASK_OKAY","reg=raider,gang|tmp=predator|st=hostile",{"I'm having the best month of my entire life - how about you?"},false,{[1]="GENERIC"}},
{"ASK_ORIGIN_TODAY","reg=civilian,family,worker,rescue|tmp=fresh|st=friendly,neutral",{"From- from over there, I don't know exactly, I got turned around, everything looks the same","Back THERE, a ways, I had to leave, it wasn't safe, it hasn't been safe for days","Home, I walked from home, and I wanted to turn back every ten steps!!","I slept in a house... last night, the owners weren't home, I'm sorry, I'm sorry, I didn't take anything","From a hiding spot, a closet, a cabinet, a crawl space, I've been hiding for days","J-just wandering, I think, I don't remember where I started, it's all a blur","I've been moving since I woke up, I can't stop, if I stop I'll cry!!"}},
{"ASK_ORIGIN_TODAY","reg=civilian,family,worker,rescue|tmp=seasoned|st=friendly,neutral",{"Out there, scavenging, looking for anything, anything that isn't nailed down","Same place I go every day, checking traps, checking fences, checking my sanity","Made the rounds, checked on the neighbors, buried one, fed another","I've been to the east side, nothing there, then back, same as yesterday","Went out for supplies, found a little, lost a little, came back"}},
{"ASK_ORIGIN_TODAY","reg=civilian,family,worker,rescue|st=careful",{"None of your business where I've been","Why? you tracking me?","Out of your way, and I'd like to keep it that way!","Around","Where I've been is my business","Far from you","Why do you care?"},false,false,{[4]={{t="that's all",afterMs=3000}}}},
{"ASK_ORIGIN_TODAY","role=civilian_loner|st=friendly,neutral",{"Followed a deer trail for six miles -- ended nowhere, same as always.."}},
{"ASK_ORIGIN_TODAY","role=worker|st=friendly,neutral",{"Checked the plant... then the yard -- then the warehouse, nothing, but at least I walked"}},
{"ASK_ORIGIN_TODAY","role=rescue_medical|st=friendly,neutral",{"Visiting patients, house to house, it's slow work, and a lot of the doors don't open","The clinic, there were supplies left, there were also patients left - I'll leave it there"}},
{"ASK_ORIGIN_TODAY","role=rescue_clergy|st=friendly,neutral",{"Walking my parish, such as it is, door to door, offering what I can","A service out by the cemetery, a short one - we keep them short now"}},
{"ASK_ORIGIN_TODAY","role=rescue_firefighter|st=friendly,neutral",{"Making rounds, checking for survivors, knocking on doors, listening"}},
{"ASK_ORIGIN_TODAY","role=militia|st=friendly,neutral",{"Perimeter walk, east to west, nothing but silence, which is never good..."}},
{"ASK_ORIGIN_TODAY","reg=raider|st=neutral,careful",{"From wherever I took something, why, you missing something?","Back where I came from, and I wasn't leaving anything behind","I come from a place that's got no use for questions","None of your business, but it was a bad place, I'm glad I left","From the last place that had something worth taking"}},
{"ASK_ORIGIN_TODAY","reg=raider|st=hostile",{"From where I made a mess, and I'm happy to make another"}},
{"ASK_ORIGIN_TODAY","reg=raider|st=friendly",{"Over in {town}, a little rough there, nothing I couldn't handle","Came up the road from a farmhouse, nice place, big pantry"}},
{"ASK_ORIGIN_TODAY","reg=gang|st=neutral,careful",{"From the block, we got people everywhere","Been moving around, checking on our people, why?","Back from a run, don't need to tell you what for","Over there, around the corner, that's all you get"}},
{"ASK_ORIGIN_TODAY","reg=gang|st=hostile",{"From somewhere you don't want to be, step off"}},
{"ASK_ORIGIN_TODAY","reg=gang|st=friendly",{"Been in {town}, crazy over there, you been?"}},
{"ASK_ORIGIN_TODAY","reg=club|st=neutral,careful",{"Rode in from the north, bad road, worse company","From a meeting with some brothers, you wouldn't know them","Been checking on the clubhouse, everything intact, mostly"}},
{"ASK_ORIGIN_TODAY","reg=club|st=hostile",{"From the last place I told someone to shut up"}},
{"ASK_ORIGIN_TODAY","reg=club|st=friendly",{"Came in from {town}, not much left, but the beer's still warm"}},
{"ASK_ORIGIN_TODAY","reg=crime|st=neutral,careful",{"A business associate's, nothing you need to know","From a conversation that didn't go my way","I was visiting someone who owed me"}},
{"ASK_ORIGIN_TODAY","reg=crime|st=friendly",{"Meeting in {town}, went fine... why, you following me?"}},
{"ASK_ORIGIN_TODAY","reg=prison|st=neutral,careful",{"Back there, behind me, I don't wanna say, I don't wanna go back","Ran from a bad place, that's all","I came from... out there, I don't know the road names","Walked all night, scared, I don't remember where it started"}},
{"ASK_ORIGIN_TODAY","reg=prison|st=hostile",{"Wherever you aren't, now leave me alone!"}},
{"ASK_ORIGIN_TODAY","reg=prison|st=friendly",{"Walked out of the county place, been on the road three days, you got any water?"}},
{"ASK_ORIGIN_TODAY","reg=outlaw|st=neutral,careful",{"Over the ridge, and I wouldn't go back that way if I were you","A hollow back there, quiet, until it wasn't","From a place I'd rather forget, thanks"}},
{"ASK_ORIGIN_TODAY","reg=outlaw|st=friendly",{"From a camp a few miles back, folks were friendly, I left before they got tired of me"}},
{"ASK_ORIGIN_TODAY","role=deserter|st=neutral,careful",{"From the base, and that's all I'm telling you","Fort Knox, but I'm not going back"}},
{"ASK_ORIGIN_TODAY","reg=law|st=neutral,careful",{"From the station, we're on patrol","Back from checking on a report, nothing there","I came from {town}, we cleared it, as much as we could"}},
{"ASK_ORIGIN_TODAY","reg=law|st=hostile",{"That's what I should be asking you, where did YOU come from?"}},
{"ASK_ORIGIN_TODAY","reg=law|st=friendly",{"Left the station earlier today, long day already, but I'm glad to meet you"}},
{"ASK_ORIGIN_TODAY","role=law_sheriff|st=neutral,careful",{"From a hard day, it's been seven of them"}},
{"ASK_ORIGIN_TODAY","role=law_trooper|st=neutral,careful",{"From the highway, there's nothing but wrecks and silence"}},
{"ASK_ORIGIN_TODAY","role=law_corrections|st=neutral,careful",{"From the facility, it's gone, all of it"}},
{"ASK_ORIGIN_TODAY","reg=swat|st=neutral,careful",{"From a staging area, can't disclose"}},
{"ASK_ORIGIN_TODAY","reg=military|st=neutral,careful",{"From the checkpoint, they pulled us back","The base, and it's not the same place anymore","From the north, they're all gone up there"}},
{"ASK_ORIGIN_TODAY","reg=military|st=hostile",{"From where I was posted, that's all you're getting"}},
{"ASK_ORIGIN_TODAY","reg=military|st=friendly",{"From a medical station, we were helping folks, you need anything?"}},
{"ASK_ORIGIN_TODAY","role=soldier_nco|st=neutral,careful",{"Out of a bad spot, sergeant said keep moving so I'm moving"}},
{"ASK_ORIGIN_TODAY","role=soldier_green|st=neutral,careful",{"From the-- from the base? I think? It's all a blur, sorry"}},
{"ASK_ORIGIN_TODAY","role=mercenary|st=neutral,careful",{"From the last job, it ended badly"}},
{"ASK_ORIGIN_TODAY","role=militia|st=neutral,careful",{"From the farm, we came down to check the road","Home, to our place on the ridge"}},
{"ASK_ORIGIN_TODAY","role=militia|st=friendly",{"From {town}, folks there are scared, but good people"}},
{"ASK_ORIGIN_TODAY","reg=civilian,family|tmp=fresh|st=friendly,neutral",{"From Riverside, I walked all night, I don't think I can feel my feet anymore"}},
{"ASK_ORIGIN_TODAY","reg=civilian|tmp=fresh|st=friendly,neutral|hour=4,11",{"The walk-in cooler at the grocery, I hid in there since this morning, you'd think I'd have liked the cold more"}},
{"ASK_ORIGIN_TODAY","role=family_woman,civilian_woman|st=friendly,neutral|world=door",{"Mama's house, she wasn't there - the door was open and the TV was still on, just static"}},
{"ASK_ORIGIN_TODAY","role=family_man,civilian_man|st=friendly,neutral|world=vehicle",{"The car, it's on the shoulder a mile back with a flat - I carried the boy the rest of the way"}},
{"ASK_ORIGIN_TODAY","role=family_youth|st=friendly,neutral",{"The high school, me and some guys were holed up in the gym - it's just me now"}},
{"ASK_ORIGIN_TODAY","role=family_elder|st=friendly,neutral",{"Walked down to check on the Pruitts, their dog came out, nobody else did"}},
{"ASK_ORIGIN_TODAY","reg=civilian,family,worker|tmp=seasoned,veteran|st=friendly,neutral|world=water",{"Over from the river, took the long way by the rail line to stay off 31W"}},
{"ASK_ORIGIN_TODAY","reg=civilian,family,worker|tmp=seasoned,veteran|st=friendly,neutral",{"Picking through houses on the east side - mostly empty - one wasn't","Came down out of March Ridge, wouldn't go back up there if you paid me in coffee"}},
{"ASK_ORIGIN_TODAY","role=militia|st=friendly,neutral|world=fence",{"Walked the fence line north, found a hole in it - fixed the hole"}},
{"ASK_ORIGIN_TODAY","reg=worker|st=friendly,neutral",{"The lumber yard, got a chainsaw going, and the noise brought company, chainsaw's still there"}},
{"ASK_ORIGIN_TODAY","role=rescue_firefighter|st=friendly,neutral|world=fire",{"A house fire on Maple, no one to call it in, it just burned, and we stood there and watched it go"}},
{"ASK_ORIGIN_TODAY","reg=civilian,family|tmp=fresh|st=careful",{"Just, back there - why? Did something follow me? Did you see something?"},false,{[1]="GENERIC"}},
{"ASK_ORIGIN_TODAY","reg=civilian,family,worker,rescue|tmp=seasoned,veteran|st=careful",{"Doesn't matter where I came from, I'm here, and you're too close"}},
{"ASK_ORIGIN_TODAY","reg=civilian,family,worker,rescue|st=hostile",{"I came from none of your business, and I'm headed the same place"}},
{"ASK_ORIGIN_TODAY","role=law_deputy,law_officer,law_sergeant|st=friendly,neutral|hour=4,9",{"House to house on {street} since sunup, nobody answered who could"}},
{"ASK_ORIGIN_TODAY","role=law_trooper|st=friendly,neutral",{"Roadblock on 31W, got relieved, if you want to call it that - nobody came, I just left"}},
{"ASK_ORIGIN_TODAY","role=law_corrections|st=friendly,neutral|world=door",{"The county jail, I held that door as long as there was a reason to"}},
{"ASK_ORIGIN_TODAY","role=law_sheriff|st=friendly,neutral|hour=4,9|world=road",{"Drove every road in this end of the county since dawn - counted the houses with lights, didn't take long"}},
{"ASK_ORIGIN_TODAY","reg=law,swat|st=careful",{"My route's not your concern - what were you doing out here?"},false,{[1]="GENERIC"}},
{"ASK_ORIGIN_TODAY","reg=law,swat|st=hostile",{"I'm asking the questions, and you're answering them on your knees"}},
{"ASK_ORIGIN_TODAY","reg=swat|st=friendly,neutral",{"Structure clearance, east side - done now"}},
{"ASK_ORIGIN_TODAY","reg=military|tmp=seasoned|st=friendly,neutral|world=cars",{"The checkpoint south of the bridge, twelve hours of turning back cars"}},
{"ASK_ORIGIN_TODAY","reg=military|tmp=veteran|st=friendly,neutral",{"Back from a sweep on the south end of Louisville - don't go there, ain't much else worth telling you"}},
{"ASK_ORIGIN_TODAY","reg=military|tmp=fresh|st=friendly,neutral,careful|day=1,12|hour=4,11",{"The base, they sent us out this morning - I'm still wearing the same socks from Friday"}},
{"ASK_ORIGIN_TODAY","reg=military|st=careful,hostile",{"Our movements are not for release, you're approaching an Army position"}},
{"ASK_ORIGIN_TODAY","reg=elite|st=friendly,neutral",{"Classified"}},
{"ASK_ORIGIN_TODAY","reg=elite|st=careful,hostile",{"You didn't see us come in, you won't see us leave"}},
{"ASK_ORIGIN_TODAY","reg=outlaw|st=friendly,neutral|world=water",{"Been keeping off the busy routes. Takes longer, and I still don't let my guard down"}},
{"ASK_ORIGIN_TODAY","role=deserter|st=friendly,neutral|world=trees",{"Up from Fort Knox, if you gotta know, took a week through the woods"}},
{"ASK_ORIGIN_TODAY","reg=outlaw|st=careful,hostile",{"Where I been ain't for sale"}},
{"ASK_ORIGIN_TODAY","reg=raider|st=friendly,neutral|world=road",{"Muldraugh, cleaned out a whole street, you might've known some of those folks - heh"}},
{"ASK_ORIGIN_TODAY","reg=gang|st=friendly,neutral",{"Riverside, had business with some people, business is done"}},
{"ASK_ORIGIN_TODAY","reg=club|st=friendly,neutral|hour=4,11|world=road",{"Rode in off the Dixie this morning, left some rubber and a couple of problems back on the road"}},
{"ASK_ORIGIN_TODAY","reg=prison|st=friendly,neutral|world=fence",{"Lockup, originally - since then? Wherever the fence wasn't"}},
{"ASK_ORIGIN_TODAY","reg=raider,gang,club,prison|st=careful",{"Came up behind you, which is where you should've been looking"}},
{"ASK_ORIGIN_TODAY","reg=raider,gang,club,prison|st=hostile",{"Where'd I come from? From the last fella who asked me questions - he's still lying there"}},
{"ASK_ORIGIN_TODAY","reg=crime|st=friendly,neutral",{"A meeting, it went well for some of us"}},
{"ASK_ORIGIN_TODAY","reg=crime|st=careful,hostile",{"Where we've been is the kind of thing people pay to forget"}},
{"ASK_OTHER_SURVIVORS","reg=civilian,family,worker,rescue|tmp=fresh|st=friendly,neutral",{"Others? There are others? tell me there are others, I haven't seen another living face in two days","A few, we've waved from a distance, nobody's brave enough to come closer","I heard people last night, laughing, real laughing!! I almost went looking for 'em, almost!!","Some -- yes, a family down the way, they have a little girl, I hear her singing sometimes","Yes! a couple of guys, and a woman with a baby, we shared a fire, then they moved on, I miss them","I don't know... I thought I saw smoke from a chimney -- but it could've been anything","Everybody's hiding, so there must be a lot of us, right? if everybody's hiding, there must be a lot of us","Not many, and the ones I've met were scared, like me, we all jump at our own shadows","I saw a few folks the other day, but they ran when they saw me, I don't blame them","You're the first living person I've talked to in days, honestly"}},
{"ASK_OTHER_SURVIVORS","reg=civilian,family,worker,rescue|tmp=seasoned|st=friendly,neutral",{"A few, scattered, mostly keeping to themselves, some are friendly, some aren't, I've learned the difference","Enough that I don't feel crazy, not enough that I feel safe","Yeah, a pocket of survivors here, a camp there, a lone wolf in the hills, we're out there","More than you'd think, fewer than you'd hope, everyone's moving, everyone's wary","Folks are dug in, boarded up, quiet as mice, you don't see them unless they want you to","I met a woman last week, she traded me a jar of peaches for a bandage, best deal of my life","A group of nine, up the road, they've got a system, but they don't let outsiders in","Some, here and there, they keep to themselves, can't blame them","A few, but trust is short supply, so be careful who you approach"}},
{"ASK_OTHER_SURVIVORS","reg=civilian,family,worker,rescue|st=friendly",{"You're looking at one, and I'm glad to meet another, believe me, glad","There's a few, and now one more, you!! That's something!","You're proof there are others"},false,false,{[3]={{t="and a good one",afterMs=3200}}}},
{"ASK_OTHER_SURVIVORS","reg=civilian,family,worker,rescue|st=careful",{"Why do you ask? looking for someone to rob?","There are no others, you hear me? none!","If there were -- I wouldn't TELL you","Maybe, maybe not, I'm not telling you","Not that I'd tell you!","Why? looking for victims?","There are none","Hmph","I'm not telling a stranger where people are - what would you do with that?","Maybe - why? Who's asking, and who's that behind you?"},false,{[9]="GENERIC",[10]="GENERIC"}},
{"ASK_OTHER_SURVIVORS","reg=civilian,family,worker,rescue|st=friendly,neutral|fact=recent_human_contact",{"Others? Yeah, just saw somebody, hold on, they were right over- they're gone now","There's a group close by, I just heard 'em, keep it quiet till we know who they are"}},
{"ASK_OTHER_SURVIVORS","role=civilian_loner",{"Couple hermits like me, some trappers, a family up on the ridge, we just nod and leave it at that","Ran into a man last week, shared a rabbit with him, we didn't exchange names, that's how I like it"}},
{"ASK_OTHER_SURVIVORS","role=family_man,family_woman",{"There's a cluster of families a mile or two off... we trade, we gossip, we check on the kids","Church group, mostly, and some neighbors, I'd say forty people within walking distance"}},
{"ASK_OTHER_SURVIVORS","role=family_elder",{"The church ladies, honey, a dozen of us, we meet on Wednesdays, no matter what"}},
{"ASK_OTHER_SURVIVORS","role=family_youth",{"Some kids from my school are around, we signal with flashlights, it's actually kind of cool"}},
{"ASK_OTHER_SURVIVORS","role=worker",{"Plant crew's scattered, a handful at the garage, a few at the depot, I don't know who's alive"}},
{"ASK_OTHER_SURVIVORS","role=rescue_medical",{"There are others, the sick and the wounded, and the ones who look after them, I see them every day"}},
{"ASK_OTHER_SURVIVORS","role=rescue_clergy",{"Beloved, you are never alone, there are always others, even if they're hidden"}},
{"ASK_OTHER_SURVIVORS","role=rescue_firefighter",{"Radio has a few voices, other units, other stations, we check in when we can"}},
{"ASK_OTHER_SURVIVORS","role=militia",{"Other watches, other posts, other men with rifles, we wave from a distance"}},
{"ASK_OTHER_SURVIVORS","reg=civilian,family,worker,rescue|st=friendly,neutral|rep=good,best",{"There's a few, yes, and they'd be glad to meet you, they've heard of you","Plenty, and the number's growing, because folks like you make it safe to come out","I know of three groups, within a day's walk, and all three would welcome you","Sure, more than you'd think, and all of them are hoping for kindness","There's a family near the creek, they trade with us, they'd love a visit","A few stragglers, a few scouts, a few hermits, I'll introduce you","They're out there, don't worry, you're not alone","There's a church group across the way, praying, singing, getting by!","A handful here, a handful there, scattered, but connected","There's talk of a gathering at the end of the month, I'd like you to come","Yes, and some of them know your name, and think highly of it","More than one, and more than two, and more than I can count on one hand","We exchange signals, so I know they're alive","The other groups would kill for someone like you!","Few and far between, but good, the good ones, I mean","I met two farmers last week, honest as the day is long","Several, each with a story, and a need","There's a woman and her three boys, hiding in a barn, I leave food out!","A couple of old-timers, tough as leather, in a farmhouse to the north","You'll find folks, if you look in the right places","Don't lose hope, there are more of us than you think","A good number, and a few great ones","A band of travelers passes through every week, with news","I've heard radio chatter, so, yes, others are out there","Depends who you ask, I've met some brave ones and some scared witless","Yes, and they're asking about you","It gets lonely, but we're not alone, I promise","We have neighbors, and the neighbors have neighbors","Quite a few, scattered across the county like stars","There's others, I'm sure of it!!"}},
{"ASK_OTHER_SURVIVORS","reg=civilian,family,worker,rescue|st=careful,neutral|rep=bad,worst",{"Others? They're avoiding you","None that'll talk to you!","There's nobody for you","Not that you'd know!","The only others I know are the ones you wronged","They're hiding from people like you","Others? Hmm, none I'd introduce you to!!","Plenty, and they all steer clear","They'd rather die than meet you","I won't lead you to them!","Everyone else knows who you are","You're welcome to look, but they won't welcome you","Not a one who'd give you the time","Ask your conscience","Others have the sense to avoid you","I know some, but they wouldn't want to know you","You don't deserve company","Why? to rob them?!","Survivors have standards","Plenty out there, none for you","No one worth meeting, from your perspective","Ask somebody else","You'd scare them off","They don't want any part of you","Don't expect a welcome!","You're on your own, and that's how it should be","I'm not the information desk","They know about you, and they've circled the wagons","Find your own friends -- if you can!","Look around, and see who's looking back!","The only ones left are tired of people like you"}},
{"ASK_OTHER_SURVIVORS","reg=civilian,family,worker,rescue|st=friendly,neutral|day=0,99999|fact=recent_zombie_contact",{"Others? I hope so, but right now it's just us and THEM","If there are others, they're hiding, as we should be","Not that I can see... only the dead!","Shh -- shh, we'll LOOK later"}},
{"ASK_OTHER_SURVIVORS","reg=civilian,family,worker,rescue|st=friendly,neutral|day=0,99999|fact=player_armed",{"You're the best sign of others I've seen all week"}},
{"ASK_OTHER_SURVIVORS","reg=civilian,family,worker,rescue|st=friendly,neutral",{"A woman and her boy, in the next valley","I heard a voice yesterday, calling a name","There's a farm family, three houses down","A preacher with a dozen followers","Oh... there are plenty","I met a man on the road","A boy about twelve","I've seen smoke from three different chimneys","Yes, and some of them are even nice","They're out there... and they're afraid of us, the same way we're afraid of them"},false,false,{[1]={{t="I leave a can on the fence post for them",afterMs=3500},{t="it's gone in the morning",afterMs=3000}},[2]={{t="over and over",afterMs=3200},{t="nobody answered",afterMs=2800}},[3]={{t="we wave",afterMs=3500},{t="that's the extent of it",afterMs=3000}},[4]={{t="they sing at night",afterMs=3200},{t="it carries",afterMs=2800}},[5]={{t="we just hide from each other",afterMs=3500}},[6]={{t="shared a fire",afterMs=3200},{t="he was gone by dawn, and so was my knife",afterMs=2800}},[7]={{t="alone",afterMs=3500},{t="I gave him my coat, and he gave me a look",afterMs=3000},{t="I don't know what it meant",afterMs=2800}},[8]={{t="I haven't gone to any of them",afterMs=3200}}}},
{"ASK_OTHER_SURVIVORS","reg=civilian,family,worker,rescue|st=friendly,neutral|mood=funny",{"Other survivors? There's a guy who plays the accordion at three in the morning"},false,false,{[1]={{t="I'm not sure he counts",afterMs=3200}}}},
{"ASK_OTHER_SURVIVORS","reg=civilian,family,worker,rescue|st=friendly,neutral|day=0,3",{"Everybody's inside, doors locked, curtains drawn","I can see lights in the neighbors' windows... so, yes.."},false,false,{[1]={{t="the whole street is holding its breath",afterMs=3500}}}},
{"ASK_OTHER_SURVIVORS","reg=civilian,family,worker,rescue|st=friendly,neutral|day=4,14",{"A few are venturing out... in pairs, in packs..","I see smoke from chimneys, so there are some"}},
{"ASK_OTHER_SURVIVORS","reg=civilian,family,worker,rescue|st=friendly,neutral|day=15,99999",{"There are communities now, here and there","We trade with the farm up the road"},false,false,{[1]={{t="tiny ones",afterMs=3500}},[2]={{t="and with a few wanderers",afterMs=3200}}}},
{"ASK_OTHER_SURVIVORS","reg=raider|st=neutral,careful",{"Other survivors? You're the first live one I've talked to in days and I haven't decided what to do with you yet","Saw a family yesterday, mom, dad, two kids, I let them keep their lives, you're welcome","There's folks around, sure, and every one of them is hiding something worth taking","Some, but they're not the friendly kind, and neither am I","Plenty hiding in cellars and attics, scared as rabbits, easy to find if you know how to listen","Why, you looking for friends? I'm the only friend you're going to find around here","Heard a baby crying a few days back, never found it... still hear it"}},
{"ASK_OTHER_SURVIVORS","reg=raider|st=hostile",{"Survivors? You're looking at one, and you're about to be a former one!","Why, you counting how many of us are left? Count to one, that's me"}},
{"ASK_OTHER_SURVIVORS","reg=raider|st=friendly",{"Honestly? I haven't seen a soul, {g:man|lady}, it's been so lonely, you're a sight for sore eyes","There was a guy and his dog, we shared a can of beans, then he left, I miss him already"}},
{"ASK_OTHER_SURVIVORS","role=raider_boss,gang_boss,biker_boss|st=neutral,careful",{"The survivors worth knowing are already working for me"}},
{"ASK_OTHER_SURVIVORS","reg=gang|st=neutral,careful",{"Few of us left on this side, we keep to ourselves","Saw some people yesterday, but we didn't stop to chat, you know how it goes","My cousins are hiding out in the basement, they won't come out for nobody","Saw three dudes pushing a cart full of cans, took one look at us and ran","Man, I miss the block party, hundreds of people, now it's me and my homies"}},
{"ASK_OTHER_SURVIVORS","reg=gang|st=hostile",{"Not telling you where anybody is, so quit asking"}},
{"ASK_OTHER_SURVIVORS","reg=gang|st=friendly",{"There's a church couple blocks over with people inside, they're cool, tell them I sent you"}},
{"ASK_OTHER_SURVIVORS","reg=club|st=neutral,careful",{"We run into folks on the road, most want something and few have anything","Our chapter's still together, a few others too, good people mostly","Saw a woman with a shotgun and a little girl, they were hungry, I left them a can","Lost count of how many we've buried, so I'd say there's not as many as there used to be"}},
{"ASK_OTHER_SURVIVORS","reg=club|st=hostile",{"Ain't going to answer questions I don't like"}},
{"ASK_OTHER_SURVIVORS","reg=club|st=friendly",{"{g:Brother|Sister}, if you find anyone, send them our way, we can help"}},
{"ASK_OTHER_SURVIVORS","reg=crime|st=neutral,careful",{"There are always survivors, the question is which are worth knowing","I've been meeting a few, selectively","Most are not interesting, a few are useful, I keep track"}},
{"ASK_OTHER_SURVIVORS","reg=crime|st=friendly",{"A group of about ten is holed up not far from here, they seem decent"}},
{"ASK_OTHER_SURVIVORS","reg=prison|st=neutral,careful",{"Other survivors? I try not to look, I try not to be seen","There's a guy named Ray in my group, he's okay, the rest I don't know","Heard voices in the woods, I didn't go closer"}},
{"ASK_OTHER_SURVIVORS","reg=prison|st=hostile",{"Why? You want to find them? Why?!"}},
{"ASK_OTHER_SURVIVORS","reg=prison|st=friendly",{"I'd love to see another face, even if it's a stranger"}},
{"ASK_OTHER_SURVIVORS","reg=outlaw|st=neutral,careful",{"A few, scattered, mostly keep to themselves","Saw smoke last week, never went to look, don't plan to","Met an old couple up the hollow, they're doing alright, got chickens"}},
{"ASK_OTHER_SURVIVORS","reg=outlaw|st=friendly",{"You're not the first one I've come across, you won't be the last"}},
{"ASK_OTHER_SURVIVORS","role=deserter|st=neutral,careful",{"I've seen a few, I don't talk to them, they ask too many questions"}},
{"ASK_OTHER_SURVIVORS","reg=law|st=neutral,careful",{"We've identified several groups of survivors, and we're trying to establish contact","We've been escorting survivors to the courthouse, about twenty so far","Reports of a church group, a farm family, and some stragglers, that's the extent of it"}},
{"ASK_OTHER_SURVIVORS","reg=law|st=hostile",{"Unauthorized gatherings are discouraged, tell me where they are"}},
{"ASK_OTHER_SURVIVORS","reg=law|st=friendly",{"Yes, there are others, and we can help you find them"}},
{"ASK_OTHER_SURVIVORS","role=law_sheriff|st=neutral,careful",{"There are survivors, and I want every one of them accounted for"}},
{"ASK_OTHER_SURVIVORS","reg=military|st=neutral,careful",{"We've encountered civilians, they've been directed to shelter in place","That is classified, so drop it","Contact with civilians is limited"}},
{"ASK_OTHER_SURVIVORS","reg=military|st=hostile",{"Civilian movements are restricted, do not wander"}},
{"ASK_OTHER_SURVIVORS","reg=military|st=friendly",{"We've helped a few families, and we'll help more if we can"}},
{"ASK_OTHER_SURVIVORS","role=soldier_nco|st=neutral,careful",{"There's survivors out there, but I can't spare the men to find them"}},
{"ASK_OTHER_SURVIVORS","role=soldier_green|st=neutral,careful",{"I saw a little girl in a window, she waved at me, I didn't know what to do"}},
{"ASK_OTHER_SURVIVORS","role=mercenary|st=neutral,careful",{"There are survivors, and some of them pay well"}},
{"ASK_OTHER_SURVIVORS","role=militia|st=neutral,careful",{"There's several farms still holding out, we keep in touch with the ones we can","A few families came to us, we took them in, put them to work","Folks across the county, hidden away, praying like us"}},
{"ASK_OTHER_SURVIVORS","role=militia|st=friendly",{"Plenty of good people left, friend, you're proof of that"}},
{"ASK_OTHER_SURVIVORS","reg=family|st=friendly,neutral",{"Oh, honey, there's folks all over, hidden, scared, waiting, just like us"}},
{"ASK_OTHER_SURVIVORS","reg=law,swat|st=friendly,neutral",{"A few groups, we're trying to organize them, slowly","Plenty sheltering in place, armed and nervous, announce yourself before you walk up on anybody's porch"}},
{"ASK_OTHER_SURVIVORS","reg=military,elite|st=friendly,neutral",{"Several, scattered, assessing"}},
{"ASK_OTHER_SURVIVORS","reg=outlaw,raider,gang,club,crime,prison|st=friendly,neutral",{"Plenty, some nice, some not, you'll know the difference when it's too late"}},
{"ASK_OTHER_SURVIVORS","reg=civilian,family|tmp=fresh|st=friendly,neutral|world=road",{"Old couple two streets over still hangs laundry out, so I know they're alive - I just don't knock"}},
{"ASK_OTHER_SURVIVORS","reg=civilian|tmp=fresh|st=friendly,neutral",{"You're the first person I've talked to in three days - sorry, I'm talking a lot - sorry"}},
{"ASK_OTHER_SURVIVORS","reg=civilian,family|tmp=fresh|st=friendly,neutral|world=building",{"The Dawsons next door are gone, but I heard kids laughing by the church yesterday - I'm sure I did"}},
{"ASK_OTHER_SURVIVORS","reg=civilian,family|st=friendly|world=road",{"We're a few families at the end of our road - we could use somebody who isn't scared of everything - would you want to join us?"},false,{[1]="JOIN_GROUP"}},
{"ASK_OTHER_SURVIVORS","reg=civilian,family|tmp=fresh|st=friendly,neutral|day=0,7|world=window",{"Lots of folks are still in their houses, waiting like they were told - you'll see curtains move when you walk past"}},
{"ASK_OTHER_SURVIVORS","reg=civilian,family|tmp=seasoned,veteran|st=friendly,neutral",{"Sure, some of them you want to meet, most you don't - learn to tell the difference from a long way off","Saw chimney smoke out toward March Ridge - in July, so somebody's cooking, and somebody isn't careful"}},
{"ASK_OTHER_SURVIVORS","reg=civilian,family|tmp=seasoned,veteran|st=friendly,neutral|day=8,9999",{"There's a few of us left in {town}, we keep to ourselves and look out for each other - that's the arrangement"}},
{"ASK_OTHER_SURVIVORS","reg=civilian,family,worker,rescue|st=hostile",{"There's one right here telling you to back off"}},
{"ASK_OTHER_SURVIVORS","reg=worker|st=friendly,neutral|world=door",{"Couple of the boys from the lumber yard are holed up in the office - forklift parked across the door"}},
{"ASK_OTHER_SURVIVORS","reg=worker,civilian|st=friendly,neutral|day=8,9999",{"Found a note taped to a payphone in West Point - names and a meeting time, the time came and went last week"}},
{"ASK_OTHER_SURVIVORS","reg=rescue|role=rescue_medical|st=friendly,neutral",{"I've treated eleven people since the clinic closed, so yes, there are survivors - some even say thank you"}},
{"ASK_OTHER_SURVIVORS","reg=rescue|role=rescue_clergy|st=friendly,neutral",{"Every Sunday a few more come to the service, some Sundays a few less - we keep the count in the back of a hymnal"}},
{"ASK_OTHER_SURVIVORS","reg=rescue|role=rescue_firefighter|st=friendly,neutral|world=door",{"We check houses when we can and mark the door - a circle means somebody's living, we've drawn a lot more X's"}},
{"ASK_OTHER_SURVIVORS","reg=law|st=friendly,neutral",{"Yes, {sir}, I've got a list of addresses with people still inside - I check on them when I can"}},
{"ASK_OTHER_SURVIVORS","reg=swat|st=friendly,neutral",{"We cleared a subdivision in Muldraugh and found nine living - nine, out of forty houses"}},
{"ASK_OTHER_SURVIVORS","reg=law,swat|st=careful,hostile",{"Whoever I know about is my business, not yours, now back up"}},
{"ASK_OTHER_SURVIVORS","reg=military|st=friendly,neutral",{"There may be other people. I'd rather talk before anybody gets frightened and does something stupid"}},
{"ASK_OTHER_SURVIVORS","reg=military|tmp=seasoned,veteran|st=friendly,neutral",{"There's pockets of them, in the towns, mostly, folks on farms do better"}},
{"ASK_OTHER_SURVIVORS","reg=military|role=soldier_green|st=friendly,neutral|world=window",{"A little girl waved at our Humvee from a window yesterday - Sergeant wouldn't let me wave back"}},
{"ASK_OTHER_SURVIVORS","reg=elite",{"Civilians present in all towns - numbers declining"}},
{"ASK_OTHER_SURVIVORS","reg=military|st=careful,hostile",{"Only survivors I care about right now are in my squad - back up"}},
{"ASK_OTHER_SURVIVORS","reg=outlaw,raider,crime|st=friendly,neutral|world=building",{"Sure, lots of 'em, every one of 'em with a pantry - I'm real interested in survivors"}},
{"ASK_OTHER_SURVIVORS","reg=prison|st=friendly,neutral",{"Found a family hiding in a church, we didn't touch 'em - not everybody who was inside is a monster, alright?"},false,{[1]="GENERIC"}},
{"ASK_OTHER_SURVIVORS","reg=gang,crime|st=friendly,neutral",{"People around, some of 'em pay us to stay that way - you interested in that kind of arrangement?"},false,{[1]="TRADE_OFFER"}},
{"ASK_OTHER_SURVIVORS","reg=club|st=friendly,neutral|world=road",{"We run into folks on the road, the ones who don't point guns at us, we share a bottle with"}},
{"ASK_OTHER_SURVIVORS","reg=outlaw,raider,gang,club,crime,prison|st=hostile",{"You're a survivor - for now"}},
{"ASK_OTHER_SURVIVORS","reg=outlaw,raider,gang,club,crime,prison|st=careful,hostile",{"There were more survivors around here before we showed up"}},
{"ASK_OTHER_SURVIVORS","reg=raider,gang,prison|st=careful,hostile",{"Why, you looking for friends? You found the wrong ones"}},
{"ASK_OTHER_SURVIVORS","reg=civilian|tmp=fresh|st=neutral|world=window",{"There was a family in the brick house on {street} - curtains are drawn, I don't knock"}},
{"ASK_OTHER_SURVIVORS","reg=family|tmp=seasoned|st=neutral",{"Folks are in more houses than you'd think, they don't come out and neither do we"}},
{"ASK_OTHER_SURVIVORS","reg=worker|tmp=seasoned|st=neutral",{"Chimney with smoke, a yard somebody mowed... mowed grass means people"}},
{"ASK_OTHER_SURVIVORS","role=rescue_clergy|st=friendly,neutral",{"Eleven of us at the church, eleven I can put a name to - there's more out there"}},
{"ASK_OTHER_SURVIVORS","role=law_deputy|st=neutral",{"I've logged forty-two living people this month, I write down every one"}},
{"ASK_OTHER_SURVIVORS","role=soldier_nco|tmp=veteran|st=neutral",{"Pockets everywhere, most won't answer a hail, I quit taking it personal"}},
{"ASK_OTHER_SURVIVORS","role=elite_delta|tmp=veteran|st=neutral",{"Yes, and every one of them is a decision you'll make in about four seconds"}},
{"ASK_OTHER_SURVIVORS","role=civilian_loner|st=careful|mood=grim",{"There's people, that ain't always the good news folks think it is"}},
{"ASK_OTHER_SURVIVORS","reg=raider,gang|tmp=predator|st=hostile",{"Survivors, yeah, we run into 'em - briefly"}},
}
